//
//  ShadowPack.swift
//  ShadowMatch
//
//  Picture packs. Each pack is 10 pictures; "Animal Friends" is free, the rest are
//  non-consumable in-app purchases (see Store/PackStore.swift + ShadowMatch.storekit).
//  Artwork: Assets.xcassets/Shadow* (generated by tools/make_shadow_animals.py + make_shadow_packs.py).
//

import SwiftUI

struct ShadowItem: Identifiable, Hashable {
    let id: String      // asset name
    let name: String    // spoken / shown name
}

struct ShadowPack: Identifiable, Hashable {
    let id: String
    let title: String
    let tagline: String
    let symbol: String
    let color: Color
    /// App Store product id; `nil` = free pack.
    let productID: String?
    /// Headline on the finish screen.
    let finishTitle: String
    let items: [ShadowItem]

    var isFree: Bool { productID == nil }

    /// A few pictures for the pack card.
    var preview: [ShadowItem] { Array(items.prefix(3)) }
}

